#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    vector<int> left_part, right_part;
    int mid_point = n / 2;

    function<void(int, int)> generate_left = [&](int i, int total) {
        if (i == mid_point) {
            left_part.push_back(total);
        } else {
            generate_left(i + 1, (total + a[i]) % m);
            generate_left(i + 1, total);
        }
    };

    function<void(int, int)> generate_right = [&](int i, int total) {
        if (i == n) {
            right_part.push_back(total);
        } else {
            generate_right(i + 1, (total + a[i]) % m);
            generate_right(i + 1, total);
        }
    };

    generate_left(0, 0);
    generate_right(mid_point, 0);

    sort(left_part.begin(), left_part.end());
    left_part.erase(unique(left_part.begin(), left_part.end()), left_part.end());

    int max_found = 0;
    for (int val : right_part) {
        int idx = (int)(lower_bound(left_part.begin(), left_part.end(), m - val) - left_part.begin());
        if (idx > 0) {
            int candidate_sum = left_part[idx - 1] + val;
            if (candidate_sum > max_found) {
                max_found = candidate_sum;
            }
        } else {
            if (val > max_found) {
                max_found = val;
            }
        }
    }
    cout << max_found << "\n";
    return 0;
}
